+            <span>Are you sure you want to revoke the session on <strong>@_sessionToRevoke?.Device</strong>?</span>
+            <span>
+                <button class="btn btn-sm btn-danger me-2" @onclick="ConfirmRevoke">Yes, Revoke</button>
+                <button class="btn btn-sm btn-outline-secondary" @onclick="CancelRevoke">Cancel</button>
+            </span>
+        </div>
+    }
+
+    <div class="table-responsive">
+        <table class="table table-sm table-hover">
+            <thead>
+                <tr>
+                    <th>Device</th>
+                    <th>Location</th>
+                    <th>Last Active</th>
+                    <th></th>
+                </tr>
+            </thead>
+            <tbody>
+                @foreach (var session in Sessions)
+                {
+                    <tr>
+                        <td>@session.Device</td>
+                        <td>@session.Location</td>
+                        <td>@FormatTime(session.LastActive)</td>
+                        <td>
+                            @if (session.Id != CurrentSessionId)
+                            {
+                                <button class="btn btn-sm btn-outline-danger" @onclick="() => RequestRevoke(session)">
+                                    Revoke
+                                </button>
+                            }
+                            else
+                            {
+                                <span class="badge bg-success">Current</span>
+                            }
+                        </td>
+                    </tr>
+                }
+            </tbody>
+        </table>
+    </div>
+</div>
+
+@code {
+    [Parameter] public List<ActiveSession> Sessions { get; set; } = new();
+    [Parameter] public string CurrentSessionId { get; set; } = "sess-1";
+    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }
+
+    private bool _showRevokeConfirm;
+    private ActiveSession? _sessionToRevoke;
+
+    private void RequestRevoke(ActiveSession session)
+    {
+        _sessionToRevoke = session;
+        _showRevokeConfirm = true;
+    }
+
+    private async Task ConfirmRevoke()
+    {
+        if (_sessionToRevoke is not null)
+        {
+            await OnRevokeSession.InvokeAsync(_sessionToRevoke.Id);
+        }
+        _showRevokeConfirm = false;
+        _sessionToRevoke = null;
+    }
+
+    private void CancelRevoke()
+    {
+        _showRevokeConfirm = false;
+        _sessionToRevoke = null;
+    }
+
+    private static string FormatTime(DateTime dt)
+    {
+        var diff = DateTime.UtcNow - dt;
+        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
+        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
+        return $"{(int)diff.TotalDays} days ago";
+    }
+}
+

