@namespace sv_73c7c7385e424e36b14c9bf782ba00e7.Components.Pages.Settings
@using sv_73c7c7385e424e36b14c9bf782ba00e7.Models
@using sv_73c7c7385e424e36b14c9bf782ba00e7.Services
@inject ISettingsService SettingsService

<div class="security-section">
    <h4 class="mb-4">Security Settings</h4>

    @if (_loading)
    {
        <p>Loading...</p>
    }
    else
    {
        <ChangePasswordPanel OnPasswordChanged="HandlePasswordChange" />

        <div class="card mb-3">
            <div class="card-body">
                <div class="d-flex justify-content-between align-items-center">
                    <div>
                        <h6 class="mb-1">Two-Factor Authentication</h6>
                        <small class="text-muted">
                            @if (_twoFactorEnabled)
                            {
                                <span class="text-success">● Enabled</span>
                            }
                            else
                            {
                                <span class="text-danger">● Disabled</span>
                            }
                        </small>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" @bind="_twoFactorEnabled" />
                    </div>
                </div>
            </div>
        </div>

        @if (_lastPasswordChange.HasValue)
        {
            <p class="text-muted small">Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }

        <ActiveSessionsTable Sessions="_sessions" CurrentSessionId="sess-1" OnRevokeSession="HandleRevokeSession" />
    }
</div>

@code {
    private bool _loading = true;
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadSettings();
        _loading = false;
    }

    private async Task LoadSettings()
    {
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions.ToList();
    }

    private async Task HandlePasswordChange()
    {
        await SettingsService.ChangePasswordAsync("", "");
        _lastPasswordChange = DateTime.UtcNow;
    }

    private async Task HandleRevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _sessions = _sessions.Where(s => s.Id != sessionId).ToList();
    }
}

